import{_ as n,o as l,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Infernalis (Day 1) -- RGW: Multitenancy","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- RGW: Multitenancy","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","RGW","Multitenancy","S3","Keystone"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Multitenancy.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Multitenancy.md","lastUpdated":1780459816000}'),a={name:"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Multitenancy.md"};function i(r,t,o,_,p,u){return l(),e("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： RGW 多租户功能讨论</p><p><strong>会议时间</strong>： 2023年11月</p><p><strong>参会人员</strong>：多位 Ceph 领域研发人员及相关技术人员</p><p><strong>会议内容</strong>：</p><p><strong>一、多租户功能概述</strong></p><ul><li>会议回顾了 RGW 的多租户功能，指出当前 RGW 用户模块采用全局命名空间，所有用户和存储桶共享同一命名空间。</li><li>为实现多租户功能，提出了每个 RGW 用户和一个存储桶拥有租户属性的方案，所有现有用户位于全局租户中，新用户将继承其租户属性。</li></ul><p><strong>二、与 S3 协议的兼容性</strong></p><ul><li>讨论了多租户功能与 S3 协议的兼容性，提出了用户可以通过指定租户访问特定存储桶，以及使用不同域名区分不同租户的存储桶。</li></ul><p><strong>三、其他功能和扩展</strong></p><ul><li>讨论了多租户功能的进一步扩展，包括在租户级别配置存储策略、提供统计信息、实现租户管理员功能等。</li></ul><p><strong>四、与 Keystone 的集成</strong></p><ul><li>讨论了多租户功能与 Keystone 的集成，提出了保持当前映射方式或映射到租户的两种方案。</li></ul><p><strong>五、角色认证</strong></p><ul><li>讨论了基于角色的认证方案，用户在特定租户中仅拥有特定权限。</li></ul><p><strong>六、S3 API 中的租户概念</strong></p><ul><li>讨论了将租户概念添加到 S3 API 中，包括 Swift。</li></ul><p><strong>七、子用户概念</strong></p><ul><li>讨论了子用户概念的利弊，认为其可能是一个“Hack”，并考虑其他替代方案。</li></ul><p><strong>八、下一步行动</strong></p><ul><li>实施多租户功能的初步方案。</li><li>与 Swift API 用户交流，了解对多租户功能的反馈。</li><li>完善测试用例，确保多租户功能正常工作。</li></ul><p><strong>九、会议总结</strong></p><ul><li>会议对 RGW 多租户功能进行了深入的讨论，并制定了下一步行动计划。多租户功能将为 Ceph 提供更好的多租户支持，并提高系统的可扩展性和安全性。</li></ul>',23)])])}const d=n(a,[["render",i]]);export{c as __pageData,d as default};
